(1919, 2, 1779165283, NULL, 'additionalhtmlfooter', '<script>\r\ndocument.addEventListener(\"DOMContentLoaded\", function() {\r\n    var isTargetPage = document.body.classList.contains(\'course-2\') || \r\n                       document.body.classList.contains(\'course-3\') || \r\n                       document.body.classList.contains(\'course-5\');\r\n                       \r\n    var isNotEditing = !document.body.classList.contains(\'editing\');\r\n\r\n    if (isTargetPage && isNotEditing) {\r\n        var drawer = document.getElementById(\'theme_boost-drawers-courseindex\');\r\n        if (drawer && drawer.classList.contains(\'show\')) {\r\n            var closeBtn = document.querySelector(\'[data-target=\"theme_boost-drawers-courseindex\"]\');\r\n            if(closeBtn) closeBtn.click();\r\n        }\r\n    }\r\n});\r\n</script>', '<script>\r\ndocument.addEventListener(\"DOMContentLoaded\", function() {\r\n    var isTargetPage = document.body.classList.contains(\'course-2\') || \r\n                       document.body.classList.contains(\'course-3\') || \r\n                       document.body.classList.contains(\'course-5\');\r\n                       \r\n    var isNotEditing = !document.body.classList.contains(\'editing\');\r\n\r\n    if (isTargetPage && isNotEditing) {\r\n        var drawer = document.getElementById(\'theme_boost-drawers-courseindex\');\r\n        if (drawer && drawer.classList.contains(\'show\')) {\r\n            var closeBtn = document.querySelector(\'[data-target=\"theme_boost-drawers-courseindex\"]\');\r\n            if(closeBtn) closeBtn.click();\r\n        }\r\n    }\r\n});\r\n</script>\r\n\r\n<script>\r\ndocument.addEventListener(\'DOMContentLoaded\', function() {\r\n    // 1. Deteksi apakah halaman ini punya kotak Live Search\r\n    var searchInput = document.getElementById(\'liveSearchInput\');\r\n    \r\n    if (searchInput) {\r\n        searchInput.addEventListener(\'keyup\', function() {\r\n            var filter = searchInput.value.toLowerCase();\r\n            \r\n            // 2. Mesin Filter untuk Tampilan BENTUK CARD (Webinar / Pemdi)\r\n            // Kita menargetkan \'.col\' agar jarak grid-nya ikut hilang saat disembunyikan\r\n            var columns = document.querySelectorAll(\'.col\'); \r\n            columns.forEach(function(col) {\r\n                // Pastikan yang difilter hanya col yang memiliki card di dalamnya\r\n                if (col.querySelector(\'.card\')) { \r\n                    var text = col.textContent || col.innerText;\r\n                    if (text.toLowerCase().indexOf(filter) > -1) {\r\n                        col.style.display = \"\"; // Munculkan\r\n                    } else {\r\n                        col.style.display = \"none\"; // Sembunyikan\r\n                    }\r\n                }\r\n            });\r\n\r\n            // 3. Mesin Filter untuk Tampilan BENTUK ACCORDION (Tahapan Evaluasi Pemdi)\r\n            var accordions = document.querySelectorAll(\'.accordion-item\');\r\n            accordions.forEach(function(acc) {\r\n                var text = acc.textContent || acc.innerText;\r\n                if (text.toLowerCase().indexOf(filter) > -1) {\r\n                    acc.style.display = \"\"; // Munculkan\r\n                } else {\r\n                    acc.style.display = \"none\"; // Sembunyikan\r\n                }\r\n            });\r\n            \r\n        });\r\n    }\r\n});\r\n</script>'),
(1920, 2, 1779262417, 'theme_boost', 'scss', '/* ==============================================================\r\n   MENYEMBUNYIKAN COURSE INDEX DI HALAMAN DINAMIS\r\n   ============================================================== */\r\n\r\n/* 1. Menyembunyikan tombol hamburger pembuka Course Index */\r\nbody.course-2:not(.editing) .drawer-toggler,\r\nbody.course-3:not(.editing) .drawer-toggler,\r\nbody.course-5:not(.editing) .drawer-toggler {\r\n    display: none !important;\r\n}\r\n\r\n/* 2. Menyembunyikan panel Course Index itu sendiri */\r\nbody.course-2:not(.editing) #theme_boost-drawers-courseindex,\r\nbody.course-3:not(.editing) #theme_boost-drawers-courseindex,\r\nbody.course-5:not(.editing) #theme_boost-drawers-courseindex {\r\n    display: none !important;\r\n    width: 0 !important;\r\n}\r\n\r\n/* 3. Memaksa konten utama melebar penuh menutupi area yang kosong\r\n      (Mengabaikan memori Moodle jika state aslinya \"Terbuka\") */\r\nbody.course-2:not(.editing),\r\nbody.course-3:not(.editing),\r\nbody.course-5:not(.editing) {\r\n    /* Menghancurkan variabel lebar laci bawaan Moodle */\r\n    --drawer-left-width: 0px !important;\r\n}\r\n\r\nbody.course-2:not(.editing) #page.drawers,\r\nbody.course-3:not(.editing) #page.drawers,\r\nbody.course-5:not(.editing) #page.drawers,\r\nbody.course-2:not(.editing) #page-wrapper,\r\nbody.course-3:not(.editing) #page-wrapper,\r\nbody.course-5:not(.editing) #page-wrapper {\r\n    margin-left: 0 !important;\r\n    padding-left: 0 !important;\r\n    width: 100% !important;\r\n    max-width: 100% !important;\r\n    left: 0 !important;\r\n}\r\n\r\n/* Mengatasi pembungkus konten di bagian dalam (inner wrapper) jika masih membandel */\r\nbody.course-2:not(.editing) #page-content,\r\nbody.course-3:not(.editing) #page-content,\r\nbody.course-5:not(.editing) #page-content {\r\n    margin-left: 0 !important;\r\n    margin-right: 0 !important;\r\n    width: 100% !important;\r\n}\r\n\r\n/* ==============================================================\r\n   MENYEMBUNYIKAN JUDUL SITUS RAKSASA DI HALAMAN BERANDA\r\n   ============================================================== */\r\nbody#page-site-index #page-header,\r\nbody#page-site-index .page-context-header,\r\nbody#page-site-index .page-header-headings {\r\n    display: none !important;\r\n}\r\n\r\n/* Merapatkan jarak agar kotak pencarian langsung naik ke atas */\r\nbody#page-site-index #region-main {\r\n    padding-top: 0 !important;\r\n    margin-top: -15px !important;\r\n}', '/* ==============================================================\r\n   MENYEMBUNYIKAN COURSE INDEX DI HALAMAN DINAMIS\r\n   ============================================================== */\r\n\r\n/* 1. Menyembunyikan tombol hamburger pembuka Course Index */\r\nbody.course-2:not(.editing) .drawer-toggler,\r\nbody.course-3:not(.editing) .drawer-toggler,\r\nbody.course-5:not(.editing) .drawer-toggler {\r\n    display: none !important;\r\n}\r\n\r\n/* 2. Menyembunyikan panel Course Index itu sendiri */\r\nbody.course-2:not(.editing) #theme_boost-drawers-courseindex,\r\nbody.course-3:not(.editing) #theme_boost-drawers-courseindex,\r\nbody.course-5:not(.editing) #theme_boost-drawers-courseindex {\r\n    display: none !important;\r\n    width: 0 !important;\r\n}\r\n\r\n/* 3. Memaksa konten utama melebar penuh menutupi area yang kosong\r\n      (Mengabaikan memori Moodle jika state aslinya \"Terbuka\") */\r\nbody.course-2:not(.editing),\r\nbody.course-3:not(.editing),\r\nbody.course-5:not(.editing) {\r\n    /* Menghancurkan variabel lebar laci bawaan Moodle */\r\n    --drawer-left-width: 0px !important;\r\n}\r\n\r\nbody.course-2:not(.editing) #page.drawers,\r\nbody.course-3:not(.editing) #page.drawers,\r\nbody.course-5:not(.editing) #page.drawers,\r\nbody.course-2:not(.editing) #page-wrapper,\r\nbody.course-3:not(.editing) #page-wrapper,\r\nbody.course-5:not(.editing) #page-wrapper {\r\n    margin-left: 0 !important;\r\n    padding-left: 0 !important;\r\n    width: 100% !important;\r\n    max-width: 100% !important;\r\n    left: 0 !important;\r\n}\r\n\r\n/* Mengatasi pembungkus konten di bagian dalam (inner wrapper) jika masih membandel */\r\nbody.course-2:not(.editing) #page-content,\r\nbody.course-3:not(.editing) #page-content,\r\nbody.course-5:not(.editing) #page-content {\r\n    margin-left: 0 !important;\r\n    margin-right: 0 !important;\r\n    width: 100% !important;\r\n}'),
