INSERT INTO `mdl_course` (`id`, `category`, `sortorder`, `fullname`, `shortname`, `idnumber`, `summary`, `summaryformat`, `format`, `showgrades`, `newsitems`, `startdate`, `enddate`, `relativedatesmode`, `marker`, `maxbytes`, `legacyfiles`, `showreports`, `visible`, `visibleold`, `downloadcontent`, `groupmode`, `groupmodeforce`, `defaultgroupingid`, `lang`, `calendartype`, `theme`, `timecreated`, `timemodified`, `requested`, `enablecompletion`, `completionnotify`, `cacherev`, `originalcourseid`, `showactivitydates`, `showcompletionconditions`, `pdfexportfont`, `enableaitools`) VALUES
(1, 0, 1, 'Teman Belajar', 'TB', '', '<p data-path-to-node=\"9,0\"><strong data-path-to-node=\"9,0\" data-index-in-node=\"0\">Teman Belajar: Tumbuh dan Berkolaborasi Bersama</strong></p>\r\n<p data-path-to-node=\"9,1\">Tingkatkan kapasitas dan wawasan Anda melalui Teman Belajar! Ini bukan sekadar repositori materi, melainkan ruang kolaborasi interaktif untuk berbagi pengetahuan dan praktik terbaik. Jelajahi Katalog Pelatihan kami untuk menemukan kursus teknis dan manajerial terbaru, ikuti sesi Webinar interaktif, dan jadilah bagian dari komunitas pembelajar yang terus berinovasi. Mari ciptakan budaya kerja yang unggul melalui literasi berkelanjutan.</p>', 0, 'site', 1, 3, 0, 0, 0, 0, 0, 0, 0, 1, 1, NULL, 0, 0, 0, '', '', '', 1776736823, 1779163144, 0, 0, 0, 1779262526, NULL, 1, NULL, NULL, NULL),
(2, 1, 10004, 'Panduan Pengguna', 'Panduan', 'Hal-00001', '<p>Halaman web Panduan Pengguna yang berfungsi dalam memberikan informasi kepada Pengguna bagaimana cara dasar memanfaatkan aplikasi Teman Belajar.</p>', 1, 'topics', 0, 5, 1767200400, 0, 0, 0, 0, 0, 0, 1, 1, NULL, 0, 0, 0, '', '', '', 1776740863, 1776741772, 0, 0, 0, 1779262526, NULL, 0, NULL, NULL, NULL),
(3, 1, 10003, 'Pertanyaan Umum', 'FAQ', 'Hal-00002', '<p>Halaman pertanyaan yang sering diajukan atau pertanyaan umum adalah daftar kumpulan tanya-jawab mengenai topik umum yang sering ditanyakan oleh Pengguna.</p>', 1, 'topics', 0, 5, 1767200400, 0, 0, 0, 0, 0, 0, 1, 1, NULL, 0, 0, 0, '', '', '', 1776822514, 1776822668, 0, 0, 0, 1779262526, NULL, 0, NULL, NULL, NULL),
(4, 11, 30001, 'Microsoft Office', 'MS Office', 'TIK.01.01.01', '<p>Kursus praktis yang dirancang khusus untuk meningkatkan kecakapan digital Peserta dalam mengoptimalkan fitur-fitur utama Microsoft Office (Word, Excel, dan PowerPoint). Fokus pembelajaran diarahkan pada efisiensi administrasi perkantoran, seperti otomatisasi dokumen kedinasan (Mail Merge), pengelolaan dan rekapitulasi data laporan menggunakan formula esensial Excel, serta penyusunan materi paparan kinerja yang profesional, struktural, dan menarik untuk pimpinan.</p>', 1, 'topics', 1, 5, 1778518800, 0, 0, 0, 0, 0, 0, 1, 1, NULL, 0, 0, 0, '', '', '', 1778466712, 1779263241, 0, 1, 0, 1779263241, NULL, 1, 1, NULL, NULL),
(5, 1, 10002, 'Webinar', 'Webinar', 'Hal-00003', '<p>Halaman interaktif yang memuat jadwal agenda siaran langsung, tautan kelas virtual (Zoom/Meet), dan arsip rekaman pelatihan terkait pengembangan kompetensi, tata kelola Pemerintah Digital (Pemdi), serta peningkatan <i data-path-to-node=\"9,0\" data-index-in-node=\"215\">soft-skill</i>.</p>', 1, 'topics', 0, 5, 1767200400, 0, 0, 0, 0, 0, 0, 1, 1, NULL, 0, 0, 0, '', '', '', 1778638900, 1778638900, 0, 0, 0, 1779262526, NULL, 0, NULL, NULL, NULL),
(6, 1, 10001, 'Pemerintah Digital', 'Pemdi', 'Hal-00004', '<div class=\"p-4 mb-4 text-white rounded-3 shadow-sm\" style=\"background-image: linear-gradient(to right, #059669, #10b981);\">\r\n<div class=\"container-fluid py-2\">\r\n<h2 class=\"fw-bold\"><i class=\"fa fa-university me-2\"></i> Portal Pemerintah Digital (Pemdi)</h2>\r\n<p class=\"fs-6 mb-0 text-white-75\">Selamat datang di Portal Pemdi. Ruang kolaborasi dan pusat informasi terpadu bagi seluruh perangkat daerah dalam menyongsong pelaksanaan Pemdi 2026. Melalui portal ini, Anda dapat mempelajari hal-hal kunci terkait tata kelola, mengunduh dokumen kebijakan, serta memantau linimasa tahapan evaluasi.</p>\r\n</div>\r\n</div>', 1, 'topics', 0, 5, 1767200400, 0, 0, 0, 0, 0, 0, 1, 1, NULL, 0, 0, 0, '', '', '', 1779078999, 1779085399, 0, 0, 0, 1779262526, NULL, 0, NULL, NULL, NULL),
(7, 17, 0, 'Audit Infrastruktur dan Aplikasi SPBE', 'AIA SPBE', '', '<p>Pelatihan AIA SPBE Audit Infrastruktur dan Aplikasi Sistem  Pemerintahan Berbasis Elektronik)  </p>', 1, 'topics', 1, 5, 1776358800, 1807952160, 0, 0, 0, 0, 0, 1, 1, NULL, 0, 0, 0, 'id', '', '', 1776412190, 1776757800, 0, 1, 0, 1779768327, NULL, 1, 1, NULL, NULL),
(8, 22, 0, 'Mikrotik Certified Network Associate (MTCNA)', 'MTCNA', '', '<p>MikroTik Certified Network Associate (MTCNA) merupakan sebuah program sertifikasi dari MikroTik untuk para Network Engineer pada tingkatan entry-level. Sertifikasi ini membantu Network Engineer untuk memahami dasar-dasar networking dan meningkatkan atau memberi nilai tambah pada Network Engineer tersebut. Training ini diperuntukkan bagi mereka yang ingin mempelajari dasar-dasar dan fungsi-fungsi yang terdapat pada MikroTik Routerboard, serta feature, implementasi dan troubleshoot secara umum.</p>', 1, 'topics', 1, 0, 1776445200, 0, 0, 0, 0, 0, 0, 1, 1, NULL, 0, 0, 0, '', '', '', 1776390255, 1776638970, 0, 1, 0, 1779768752, NULL, 1, 1, NULL, NULL),
(9, 14, 0, 'IT Infrastructure Library 4 Foundation', 'ITIL', '', '<p data-path-to-node=\"0\"><strong data-path-to-node=\"0\" data-index-in-node=\"66\">ITIL 4 Foundation</strong> adalah sebuah kerangka kerja (<em>framework</em>) manajemen layanan modern yang dirancang untuk membantu organisasi mengelola layanan berbasis teknologi di era digital. ITIL 4 Foundation adalah panduan yang mengajarkan cara menyatukan aspek bisnis, teknologi, dan operasional agar bekerja secara harmonis.</p>', 1, 'topics', 1, 5, 1776618000, 0, 0, 0, 0, 0, 0, 1, 1, NULL, 0, 0, 0, '', '', '', 1771405004, 1776405777, 0, 1, 0, 1779769083, NULL, 1, 1, NULL, NULL);
