INSERT INTO `mdl_label` (`id`, `course`, `name`, `intro`, `introformat`, `timemodified`) VALUES
(1, 4, 'Format Dasar dan Dokumen Resmi', '', 1, 1778467590),
(2, 4, 'Format Dasar dan Dokumen Resmi', '<h5 style=\"text-align: center;\"><strong>Format Dasar dan Dokumen Resmi</strong></h5>', 1, 1778468655),
(3, 4, 'Otomatisasi Persuratan', '<h5 style=\"text-align: center;\"><strong>Otomatisasi Persuratan</strong></h5>', 1, 1778470916),
(4, 4, 'Formula Esensial', '<h5 style=\"text-align: center;\"><strong>Formula Esensial</strong></h5>', 1, 1778471825),
(5, 4, 'Analisis dan Visualisasi Data', '<h5 style=\"text-align: center;\"><strong>Analisis dan Visualisasi Data</strong></h5>', 1, 1778471978),
(6, 4, 'Praktik Mandiri', '<h5 style=\"text-align: center;\"><strong>Praktik Mandiri</strong></h5>', 1, 1778472326),
(7, 4, 'Praktik Mandiri', '<h5 style=\"text-align: center;\"><strong>Praktik Mandiri</strong></h5>', 1, 1778472399),
(8, 4, 'Desain dan Estetika Presentasi', '<h5 style=\"text-align: center;\"><strong>Desain dan Estetika Presentasi</strong></h5>', 1, 1778472578),
(9, 4, 'Elemen Interaktif', '<h5 style=\"text-align: center;\" data-path-to-node=\"14,1,0\"><strong>Elemen Interaktif</strong></h5>', 1, 1778473472),
(10, 4, 'Praktik Mandiri', '<h5 style=\"text-align: center;\"><strong>Praktik Mandiri</strong></h5>', 1, 1778480601),
(11, 5, 'Pusat Kelas Virtual', '<div class=\"p-4 mb-4 bg-primary text-white rounded-3 shadow-sm\" style=\"background-image: linear-gradient(to right, #0d6efd, #0dcaf0);\">\r\n<div class=\"container-fluid py-2\">\r\n<h2 class=\"fw-bold\"><i class=\"fa fa-video-camera me-2\"></i> Pusat Kelas Virtual</h2>\r\n<p class=\"fs-6 mb-0 text-white-50\">Tingkatkan kompetensi digital Anda melalui sesi siaran langsung dan diskusi interaktif.</p>\r\n</div>\r\n</div>\r\n<ul id=\"webinarTabs\" class=\"nav nav-pills mb-4 list-unstyled\" style=\"list-style-type: none !important; margin-left: 0; padding-left: 0;\" role=\"tablist\">\r\n<li class=\"nav-item\" role=\"presentation\"><button id=\"upcoming-tab\" class=\"nav-link active fw-bold\" role=\"tab\" type=\"button\" data-bs-toggle=\"pill\" data-bs-target=\"#upcoming\" aria-controls=\"upcoming\" aria-selected=\"true\">Jadwal Mendatang</button></li>\r\n<li class=\"nav-item\" role=\"presentation\"><button id=\"archive-tab\" class=\"nav-link fw-bold\" role=\"tab\" type=\"button\" data-bs-toggle=\"pill\" data-bs-target=\"#archive\" aria-controls=\"archive\" aria-selected=\"false\">Arsip &amp; Rekaman</button></li>\r\n</ul>\r\n<div id=\"webinarTabsContent\" class=\"tab-content\">\r\n<div id=\"upcoming\" class=\"tab-pane fade show active\" role=\"tabpanel\" aria-labelledby=\"upcoming-tab\">\r\n<div class=\"row row-cols-1 row-cols-md-2 g-4\">\r\n<div class=\"col\">\r\n<div class=\"card h-100 shadow-sm border-0 border-start border-5 border-success\">\r\n<div class=\"card-body\"><span class=\"badge bg-success mb-2\"><i class=\"fa fa-circle text-white me-1\"></i> Live Hari Ini</span>\r\n<h5 class=\"card-title text-dark fw-bold\">Sosialisasi Arsitektur Pemdi 2026</h5>\r\n<p class=\"card-text text-muted small mb-3\"><i class=\"fa fa-calendar me-1\"></i> Rabu, 13 Mei 2026 | 13:00 - 15:00 WIB</p>\r\n<p class=\"card-text\">Pemaparan integrasi sistem layanan digital untuk seluruh perangkat daerah.</p>\r\n</div>\r\n<div class=\"card-footer bg-white border-0 pb-3\"><a class=\"btn btn-primary w-100\" href=\"https://meet.google.com/YOUR-MEET-LINK\" target=\"_blank\" rel=\"noopener\"><i class=\"fa fa-play-circle me-1\"></i> Masuk Ruang Google Meet</a></div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card h-100 shadow-sm border-0 border-start border-5 border-warning\">\r\n<div class=\"card-body\"><span class=\"badge bg-warning text-dark mb-2\">Segera Datang</span>\r\n<h5 class=\"card-title text-dark fw-bold\">Keamanan Informasi &amp; Anti-Phishing</h5>\r\n<p class=\"card-text text-muted small mb-3\"><i class=\"fa fa-calendar me-1\"></i> Jumat, 15 Mei 2026 | 09:00 - 11:30 WIB</p>\r\n<p class=\"card-text\">Mengenal ancaman siber dan cara melindungi data tata naskah dinas.</p>\r\n</div>\r\n<div class=\"card-footer bg-white border-0 pb-3\"><button class=\"btn btn-outline-secondary w-100\" disabled=\"disabled\">Tautan Belum Dibuka</button></div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div id=\"archive\" class=\"tab-pane fade\" role=\"tabpanel\" aria-labelledby=\"archive-tab\">\r\n<div class=\"row row-cols-1 row-cols-md-2 g-4\">\r\n<div class=\"col\">\r\n<div class=\"card h-100 shadow-sm border-0 bg-light\">\r\n<div class=\"card-body\"><span class=\"badge bg-secondary mb-2\">Selesai</span>\r\n<h5 class=\"card-title text-dark\">Literasi Digital: Optimalisasi Microsoft Office</h5>\r\n<p class=\"card-text text-muted small mb-3\"><i class=\"fa fa-calendar-check-o me-1\"></i> Sesi Mei Minggu Ke-1</p>\r\n<p class=\"card-text\">Pelajari cara menggunakan Mail Merge dan formula otomatis Excel.</p>\r\n</div>\r\n<div class=\"card-footer bg-light border-0 pb-3\"><a class=\"btn btn-outline-dark w-100\" href=\"/course/view.php?id=10\"><i class=\"fa fa-youtube-play me-1\"></i> Tonton Rekaman Kelas</a></div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>', 1, 1778654856),
(12, 6, 'Pemerintah Digital 2026', '<div class=\"p-4 mb-4 text-white rounded-3 shadow-sm\" style=\"background-image: linear-gradient(to right, #059669, #10b981);\">\r\n<div class=\"container-fluid py-2\">\r\n<h2 class=\"fw-bold\"><i class=\"fa fa-university me-2\"></i> Portal Pemerintah Digital (Pemdi)</h2>\r\n<p class=\"fs-6 mb-0 text-white-75\">Selamat datang di Portal Pemdi. Ruang kolaborasi dan pusat informasi terpadu bagi seluruh perangkat daerah dalam menyongsong pelaksanaan Pemdi 2026. Melalui portal ini, Anda dapat mempelajari hal-hal kunci terkait tata kelola, mengunduh dokumen kebijakan, serta memantau linimasa tahapan evaluasi.</p>\r\n</div>\r\n</div>', 1, 1779085253),
(13, 6, 'Cari', '<div class=\"mb-4\">\r\n<div class=\"input-group input-group-lg shadow-sm\"><i class=\"fa fa-search\"></i> <input id=\"liveSearchInput\" class=\"form-control border-0\" type=\"text\" placeholder=\"Filter teks, judul, atau jadwal di halaman ini...\"></div>\r\n</div>', 1, 1779164830);
