INSERT INTO `mdl_question` (`id`, `parent`, `name`, `questiontext`, `questiontextformat`, `generalfeedback`, `generalfeedbackformat`, `defaultmark`, `penalty`, `qtype`, `length`, `stamp`, `timecreated`, `timemodified`, `createdby`, `modifiedby`) VALUES
(1, 0, 'Fitur Margin', '<p>Apa fungsi utama dari fitur \'Margins\' pada Microsoft Word, khususnya dalam konteks penyusunan Tata Naskah Dinas?</p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'temanbelajar.local+260512022115+7ObkVy', 1778552475, 1778552475, 2, 2),
(2, 0, 'Fitur Margin', '<p>Apa fungsi utama dari fitur \'Margins\' pada Microsoft Word, khususnya dalam konteks penyusunan Tata Naskah Dinas?</p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'temanbelajar.local+260512022347+7gWfx4', 1778552627, 1778552627, 2, 2),
(3, 0, 'Fitur Mail Merge', '<p>Fitur apa di Microsoft Word yang paling efisien digunakan untuk membuat puluhan surat undangan dinas dengan isi yang sama namun nama penerima yang berbeda-beda?</p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'temanbelajar.local+260512022905+g9c667', 1778552945, 1778552945, 2, 2),
(4, 0, 'Fitur Mail Merge', '<p>Fitur apa di Microsoft Word yang paling efisien digunakan untuk membuat puluhan surat undangan dinas dengan isi yang sama namun nama penerima yang berbeda-beda?</p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'temanbelajar.local+260512022952+ZDRpJZ', 1778552992, 1778552992, 2, 2),
(5, 0, 'Fitur Table of Contents', '<p>Agar daftar isi (Table of Contents) dapat dibuat dan diperbarui secara otomatis di Microsoft Word, teks judul dan subjudul harus diformat menggunakan...</p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'temanbelajar.local+260512023353+T7vMVt', 1778553233, 1778553233, 2, 2),
(6, 0, 'Fitur Table of Contents', '<p>Agar daftar isi (Table of Contents) dapat dibuat dan diperbarui secara otomatis di Microsoft Word, teks judul dan subjudul harus diformat menggunakan...</p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'temanbelajar.local+260512023417+ALlF7b', 1778553257, 1778553257, 2, 2),
(7, 0, 'Fungsi VLookup', '<p>Fungsi Microsoft Excel mana yang paling tepat digunakan untuk mencari data tertentu secara vertikal (dari atas ke bawah) pada sebuah tabel berdasarkan nilai kunci referensi?</p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'temanbelajar.local+260512023811+C2wyOi', 1778553491, 1778553491, 2, 2),
(8, 0, 'Fungsi IF', '<p>Jika Anda ingin menampilkan kata \'LULUS\' apabila nilai pada sel A1 lebih dari 70, dan \'GAGAL\' jika kurang dari atau sama dengan 70, rumus apa yang benar?</p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'temanbelajar.local+260512024152+wjOk1l', 1778553712, 1778553712, 2, 2),
(9, 0, 'Fitur PivotTable', '<p>Fitur tingkat lanjut di Microsoft Excel yang sangat berguna untuk merangkum, mengeksplorasi, dan menyajikan data dari tabel besar secara interaktif tanpa harus menggunakan rumus yang rumit adalah...</p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'temanbelajar.local+260512024517+ogEMEe', 1778553917, 1778553917, 2, 2),
(10, 0, 'Fungsi SUM', '<p>Rumus dasar yang digunakan untuk menjumlahkan total Rencana Anggaran Biaya (RAB) dalam suatu kolom di Microsoft Excel adalah...</p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'temanbelajar.local+260512070006+57lO0B', 1778569206, 1778569206, 2, 2),
(11, 0, 'Hindari Slide Penuh Teks', '<p>Dalam penyusunan slide presentasi Microsoft PowerPoint untuk pimpinan, prinsip desain yang sangat disarankan agar paparan efektif adalah...</p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'temanbelajar.local+260512070252+3Aw9kG', 1778569372, 1778569372, 2, 2),
(12, 0, 'Fitur SmartArt', '<p>Fitur di PowerPoint yang memudahkan pengguna untuk membuat diagram terstruktur yang terlihat profesional, seperti struktur organisasi atau alur proses, dengan cepat adalah...</p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'temanbelajar.local+260512070511+VbmFfn', 1778569511, 1778569511, 2, 2),
(13, 0, 'Fitur Data Excel di PPT', '<p>Jika Anda menempelkan (Paste) grafik dari Excel ke PowerPoint dengan menggunakan opsi \'Keep Source Formatting &amp; Link Data\', apa yang akan terjadi jika data sumber di Excel tersebut Anda ubah?</p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'temanbelajar.local+260512070827+iL7dIW', 1778569707, 1778569707, 2, 2),
(14, 0, 'Pertanyaan 1', '<p>Beberapa tugas Auditee adalah :</p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, '192.168.19.27+260422024349+cvdpCz', 1776825829, 1776825830, 2, 2),
