INSERT INTO `mdl_question_attempts` (`id`, `questionusageid`, `slot`, `behaviour`, `questionid`, `variant`, `maxmark`, `minfraction`, `maxfraction`, `flagged`, `questionsummary`, `rightanswer`, `responsesummary`, `timemodified`) VALUES
(1, 1, 1, 'deferredfeedback', 1, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Apa fungsi utama dari fitur \'Margins\' pada Microsoft Word, khususnya dalam konteks penyusunan Tata Naskah Dinas?\n: Menambahkan nomor halaman secara otomatis di bagian bawah dokumen.\n; Mengatur jarak antara tepi kertas dengan teks dokumen.\n; Menyisipkan tabel dan gambar ke dalam halaman dokumen.\n', 'Mengatur jarak antara tepi kertas dengan teks dokumen.\n', NULL, 1778552507),
(2, 2, 1, 'deferredfeedback', 2, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Apa fungsi utama dari fitur \'Margins\' pada Microsoft Word, khususnya dalam konteks penyusunan Tata Naskah Dinas?\n: Mengubah ukuran dan jenis huruf pada dokumen secara keseluruhan.\n; Menyisipkan tabel dan gambar ke dalam halaman dokumen.\n; Menambahkan nomor halaman secara otomatis di bagian bawah dokumen.\n; Mengatur jarak antara tepi kertas dengan teks dokumen.\n', 'Mengatur jarak antara tepi kertas dengan teks dokumen.\n', NULL, 1778552649),
(3, 3, 1, 'deferredfeedback', 3, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Fitur apa di Microsoft Word yang paling efisien digunakan untuk membuat puluhan surat undangan dinas dengan isi yang sama namun nama penerima yang berbeda-beda?\n: Macros\n; Table of Contents\n; Track Changes\n; Mail Merge\n', 'Mail Merge\n', 'Mail Merge\n', 1778552966),
(4, 4, 1, 'deferredfeedback', 5, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Agar daftar isi (Table of Contents) dapat dibuat dan diperbarui secara otomatis di Microsoft Word, teks judul dan subjudul harus diformat menggunakan...\n: Fitur Bullet and Numbering\n; Ukuran font yang lebih besar dari teks paragraf\n; Fitur Styles (seperti Heading 1, Heading 2, dst.)\n; Penebalan (Bold) dan Garis Bawah (Underline) secara manual\n', 'Fitur Styles (seperti Heading 1, Heading 2, dst.)\n', NULL, 1778553239),
(5, 5, 1, 'deferredfeedback', 5, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Agar daftar isi (Table of Contents) dapat dibuat dan diperbarui secara otomatis di Microsoft Word, teks judul dan subjudul harus diformat menggunakan...\n: Ukuran font yang lebih besar dari teks paragraf\n; Fitur Styles (seperti Heading 1, Heading 2, dst.)\n; Fitur Bullet and Numbering\n; Penebalan (Bold) dan Garis Bawah (Underline) secara manual\n', 'Fitur Styles (seperti Heading 1, Heading 2, dst.)\n', 'Fitur Styles (seperti Heading 1, Heading 2, dst.)\n', 1778553250),
(6, 6, 1, 'deferredfeedback', 7, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Fungsi Microsoft Excel mana yang paling tepat digunakan untuk mencari data tertentu secara vertikal (dari atas ke bawah) pada sebuah tabel berdasarkan nilai kunci referensi?\n: AVERAGE\n; VLOOKUP\n; HLOOKUP\n; SUMIF\n', 'VLOOKUP\n', 'VLOOKUP\n', 1778553511),
(7, 7, 1, 'deferredfeedback', 8, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Jika Anda ingin menampilkan kata \'LULUS\' apabila nilai pada sel A1 lebih dari 70, dan \'GAGAL\' jika kurang dari atau sama dengan 70, rumus apa yang benar?\n: =IF(A1>70, \"LULUS\", \"GAGAL\")\n; =SUM(A1>70, \"LULUS\", \"GAGAL\")\n; =VLOOKUP(A1>70, \"LULUS\", \"GAGAL\")\n; =COUNTIF(A1>70, \"LULUS\", \"GAGAL\")\n', '=IF(A1>70, \"LULUS\", \"GAGAL\")\n', NULL, 1778553726),
(8, 8, 1, 'deferredfeedback', 8, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Jika Anda ingin menampilkan kata \'LULUS\' apabila nilai pada sel A1 lebih dari 70, dan \'GAGAL\' jika kurang dari atau sama dengan 70, rumus apa yang benar?\n: =COUNTIF(A1>70, \"LULUS\", \"GAGAL\")\n; =VLOOKUP(A1>70, \"LULUS\", \"GAGAL\")\n; =IF(A1>70, \"LULUS\", \"GAGAL\")\n; =SUM(A1>70, \"LULUS\", \"GAGAL\")\n', '=IF(A1>70, \"LULUS\", \"GAGAL\")\n', '=IF(A1>70, \"LULUS\", \"GAGAL\")\n', 1778553765),
(9, 9, 1, 'deferredfeedback', 9, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Fitur tingkat lanjut di Microsoft Excel yang sangat berguna untuk merangkum, mengeksplorasi, dan menyajikan data dari tabel besar secara interaktif tanpa harus menggunakan rumus yang rumit adalah...\n: Format Painter\n; PivotTable\n; Conditional Formatting\n; Data Validation\n', 'PivotTable\n', 'PivotTable\n', 1778553929),
(10, 10, 1, 'deferredfeedback', 10, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Rumus dasar yang digunakan untuk menjumlahkan total Rencana Anggaran Biaya (RAB) dalam suatu kolom di Microsoft Excel adalah...\n: =MAX()\n; =COUNT()\n; =SUM()\n; =AVERAGE()\n', '=SUM()\n', '=SUM()\n', 1778569218),
(11, 11, 1, 'deferredfeedback', 11, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Dalam penyusunan slide presentasi Microsoft PowerPoint untuk pimpinan, prinsip desain yang sangat disarankan agar paparan efektif adalah...\n: Menghindari \'Slide Penuh Teks\' dengan menggunakan poin-poin utama dan visualisasi yang relevan.\n; Memasukkan seluruh teks paragraf dari dokumen laporan ke dalam satu slide.\n; Menggunakan banyak jenis font yang berbeda di setiap slide agar terlihat meriah.\n; Menambahkan animasi berputar-putar pada setiap kata agar menarik perhatian.\n', 'Menghindari \'Slide Penuh Teks\' dengan menggunakan poin-poin utama dan visualisasi yang relevan.\n', 'Menghindari \'Slide Penuh Teks\' dengan menggunakan poin-poin utama dan visualisasi yang relevan.\n', 1778569384),
(12, 12, 1, 'deferredfeedback', 12, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Fitur di PowerPoint yang memudahkan pengguna untuk membuat diagram terstruktur yang terlihat profesional, seperti struktur organisasi atau alur proses, dengan cepat adalah...\n: Shapes\n; WordArt\n; Chart\n; SmartArt\n', 'SmartArt\n', 'SmartArt\n', 1778569521),
(13, 13, 1, 'deferredfeedback', 13, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Jika Anda menempelkan (Paste) grafik dari Excel ke PowerPoint dengan menggunakan opsi \'Keep Source Formatting & Link Data\', apa yang akan terjadi jika data sumber di Excel tersebut Anda ubah?\n: Grafik di PowerPoint tidak akan mengalami perubahan apa pun.\n; PowerPoint akan selalu meminta Anda mengetik ulang data secara manual.\n; Grafik di PowerPoint akan ikut diperbarui secara otomatis sesuai dengan perubahan di Excel.\n; Grafik di PowerPoint akan terhapus karena perbedaan format file.\n', 'Grafik di PowerPoint akan ikut diperbarui secara otomatis sesuai dengan perubahan di Excel.\n', 'Grafik di PowerPoint akan ikut diperbarui secara otomatis sesuai dengan perubahan di Excel.\n', 1778569722),
(14, 14, 1, 'deferredfeedback', 2, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Apa fungsi utama dari fitur \'Margins\' pada Microsoft Word, khususnya dalam konteks penyusunan Tata Naskah Dinas?\n: Menyisipkan tabel dan gambar ke dalam halaman dokumen.\n; Mengubah ukuran dan jenis huruf pada dokumen secara keseluruhan.\n; Mengatur jarak antara tepi kertas dengan teks dokumen.\n; Menambahkan nomor halaman secara otomatis di bagian bawah dokumen.\n', 'Mengatur jarak antara tepi kertas dengan teks dokumen.\n', 'Mengatur jarak antara tepi kertas dengan teks dokumen.\n', 1778569877),
(15, 14, 2, 'deferredfeedback', 13, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Jika Anda menempelkan (Paste) grafik dari Excel ke PowerPoint dengan menggunakan opsi \'Keep Source Formatting & Link Data\', apa yang akan terjadi jika data sumber di Excel tersebut Anda ubah?\n: Grafik di PowerPoint tidak akan mengalami perubahan apa pun.\n; Grafik di PowerPoint akan terhapus karena perbedaan format file.\n; Grafik di PowerPoint akan ikut diperbarui secara otomatis sesuai dengan perubahan di Excel.\n; PowerPoint akan selalu meminta Anda mengetik ulang data secara manual.\n', 'Grafik di PowerPoint akan ikut diperbarui secara otomatis sesuai dengan perubahan di Excel.\n', 'Grafik di PowerPoint akan ikut diperbarui secara otomatis sesuai dengan perubahan di Excel.\n', 1778569877),
(16, 14, 3, 'deferredfeedback', 9, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Fitur tingkat lanjut di Microsoft Excel yang sangat berguna untuk merangkum, mengeksplorasi, dan menyajikan data dari tabel besar secara interaktif tanpa harus menggunakan rumus yang rumit adalah...\n: Conditional Formatting\n; Format Painter\n; Data Validation\n; PivotTable\n', 'PivotTable\n', 'PivotTable\n', 1778569877),
(17, 14, 4, 'deferredfeedback', 12, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Fitur di PowerPoint yang memudahkan pengguna untuk membuat diagram terstruktur yang terlihat profesional, seperti struktur organisasi atau alur proses, dengan cepat adalah...\n: SmartArt\n; Chart\n; WordArt\n; Shapes\n', 'SmartArt\n', 'SmartArt\n', 1778569877),
(18, 14, 5, 'deferredfeedback', 6, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Agar daftar isi (Table of Contents) dapat dibuat dan diperbarui secara otomatis di Microsoft Word, teks judul dan subjudul harus diformat menggunakan...\n: Fitur Bullet and Numbering\n; Penebalan (Bold) dan Garis Bawah (Underline) secara manual\n; Ukuran font yang lebih besar dari teks paragraf\n; Fitur Styles (seperti Heading 1, Heading 2, dst.)\n', 'Fitur Styles (seperti Heading 1, Heading 2, dst.)\n', 'Fitur Styles (seperti Heading 1, Heading 2, dst.)\n', 1778569877),
(19, 14, 6, 'deferredfeedback', 8, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Jika Anda ingin menampilkan kata \'LULUS\' apabila nilai pada sel A1 lebih dari 70, dan \'GAGAL\' jika kurang dari atau sama dengan 70, rumus apa yang benar?\n: =COUNTIF(A1>70, \"LULUS\", \"GAGAL\")\n; =IF(A1>70, \"LULUS\", \"GAGAL\")\n; =SUM(A1>70, \"LULUS\", \"GAGAL\")\n; =VLOOKUP(A1>70, \"LULUS\", \"GAGAL\")\n', '=IF(A1>70, \"LULUS\", \"GAGAL\")\n', '=IF(A1>70, \"LULUS\", \"GAGAL\")\n', 1778569877),
