INSERT INTO `mdl_tiny_autosave` (`id`, `elementid`, `contextid`, `pagehash`, `userid`, `drafttext`, `draftid`, `pageinstance`, `timemodified`) VALUES
(9, 'id_summary_editor', 16, '0f95e2d84a48f2a93862d6577ac2f864cd04ff07', 2, '<p>Halaman web Panduan Pengguna yang berfungsi dalam memberikan informasi kepada Pengguna bagaimana cara dasar memanfaatkan aplikasi Teman Belajar.</p>', NULL, '19016acd207d0664ef1fcab394c8dbea', 1779084961),
(17, 'id_summary_editor', 19, 'b9e716c2082030cd1d94f67d2feea7607f1c40d2', 2, '<p>Halaman pertanyaan yang sering diajukan atau pertanyaan umum adalah daftar kumpulan tanya-jawab mengenai topik umum yang sering ditanyakan oleh Pengguna.</p>', NULL, '7acc47df2f98e2010b79f474fb1fec01', 1776824013),
(34, 'id_introeditor', 22, '94debbbccfd3ee6c998caaeee7f16315e18e0e4f', 2, '', 137587192, '0a4ad9ee0510554ba39f40da77a0e3c7', 1776827455),
(35, 'id_page', 22, '397351015944b4c2f4e58684ed54db0e07d756de', 2, '<div id=\"faqTemanBelajar\" class=\"accordion\">\n<div class=\"accordion-item\">\n<h2 id=\"headingOne\" class=\"accordion-header\"><button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapseOne\" aria-expanded=\"false\" aria-controls=\"collapseOne\"> Bagaimana cara masuk (login) ke dalam Teman Belajar? </button></h2>\n<div id=\"collapseOne\" class=\"accordion-collapse collapse\" aria-labelledby=\"headingOne\" data-bs-parent=\"#faqTemanBelajar\">\n<div class=\"accordion-body\">Gunakan email (atau nama pengguna) dan kata sandi yang telah didaftarkan. Jika Anda belum memiliki akun, silakan hubungi administrator dari Diskominfo Kota Depok.</div>\n</div>\n</div>\n<div class=\"accordion-item\">\n<h2 id=\"headingTwo\" class=\"accordion-header\"><button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapseTwo\" aria-expanded=\"false\" aria-controls=\"collapseTwo\"> Apa yang harus saya lakukan jika lupa kata sandi? </button></h2>\n<div id=\"collapseTwo\" class=\"accordion-collapse collapse\" aria-labelledby=\"headingTwo\" data-bs-parent=\"#faqTemanBelajar\">\n<div class=\"accordion-body\">Klik tautan \"Lupa kata sandi\" di halaman login, masukkan email resmi Anda, dan ikuti instruksi pemulihan yang dikirimkan ke email.</div>\n</div>\n</div>\n</div>', NULL, '3e7e23e8f0659bf2a536ec349857f433', 1776827455),
(36, 'id_introeditor', 18, '2e6214b2a3b8d5a84389e6d2f306de0a4a722be3', 2, '<p>Panduan pemanfaatan aplikasi Teman Belajar bagi Pengguna agar dapat dengan mudah dalam melakukan Pendaftaran, Pengaksesan Sistem, dan Memulai Kursus</p>', NULL, '61a4f4788c5eb500aa89899f1b442e99', 1776829211),
(49, 'id_description_editor', 36, '58e9824cf07f258e07c29a3ac3948b7acf330e29', 2, '', 12138051, '5d6ec09af56c3f9883925f57ed1be926', 1777451352),
(50, 'id_description_editor', 36, 'bb7cc86cae92775e7292a433cf2a4d945b0231db', 2, '', 884227769, 'f0078123d8455f72b571c521c86bfab7', 1777451407),
(53, 'id_description_editor', 3, '119c1a416a682c381e10f5ed88e9450290b03d5a', 2, '', 242351340, '42d4d38051ab16fe828f68b825ba1c3d', 1777866420),
